using System;
using System.Diagnostics;

// PROGRAM: Menginspeksi Generasi GC dan Pengaruh Alokasi
Console.WriteLine("=== INFORMASI RUNTIME GARBAGE COLLECTOR ===");
Console.WriteLine($"Is Server GC Active? : {System.Runtime.GCSettings.IsServerGC}");
Console.WriteLine($"GC Latency Mode      : {System.Runtime.GCSettings.LatencyMode}");
Console.WriteLine($"Total Memory Terpakai: {GC.GetTotalMemory(false) / 1024} KB");

// Mengamati promosi generasi objek
object obj = new object();
Console.WriteLine($"\nObjek baru lahir di Generasi: {GC.GetGeneration(obj)}"); // Gen 0

// Paksa GC Gen 0 berjalan
GC.Collect(0, GCCollectionMode.Forced);
Console.WriteLine($"Setelah GC Gen 0, objek promosi ke Generasi: {GC.GetGeneration(obj)}"); // Gen 1

// Paksa GC Gen 1 berjalan
GC.Collect(1, GCCollectionMode.Forced);
Console.WriteLine($"Setelah GC Gen 1, objek promosi ke Generasi: {GC.GetGeneration(obj)}"); // Gen 2

Console.WriteLine($"\nHitungan Koleksi Sejauh Ini -> Gen 0: {GC.CollectionCount(0)} | Gen 1: {GC.CollectionCount(1)} | Gen 2: {GC.CollectionCount(2)}");

