using System;

public class Solution
{
    public static void Main()
    {
        string? line = Console.ReadLine();
        if (!long.TryParse(line, out long bytes)) return;

        if (bytes >= 85000)
        {
            Console.WriteLine("HEAP: LOH (Direct Allocation)");
        }
        else
        {
            Console.WriteLine("HEAP: SOH (Generation 0)");
        }
    }
}

