using System;

public class MemoryAllocationInspector
{
    public const int LohThresholdBytes = 85000;

    public static bool IsLargeObjectHeapAllocation(int byteSize)
    {
        if (byteSize <= 0) return false;
        return byteSize >= LohThresholdBytes;
    }

    public static void Main()
    {
        Console.WriteLine(IsLargeObjectHeapAllocation(1024));
        Console.WriteLine(IsLargeObjectHeapAllocation(85000));
        Console.WriteLine(IsLargeObjectHeapAllocation(100000));
    }
}
